        return 0;
    }

    int maxLength = 0;

    for (int length = 1; length <= strings.get(0).length(); length++) {
        for (int start = 0; start <= strings.get(0).length() - length; start++) {
            String substring = strings.get(0).substring(start, start + length);
            String reversedSubstring = new StringBuilder(substring).reverse().toString();

            boolean allContain = true;
            for (String str : strings) {
                if (!str.contains(substring) && !str.contains(reversedSubstring)) {
                    allContain = false;
                    break;
                }
